import {Game} from './game.js';
import {CHAPTERS,PAGES,DIFFICULTIES,TILE} from './data.js';
const $=s=>document.querySelector(s);
let settings={volume:.6,quality:'high',subtitles:true,motion:matchMedia('(prefers-reduced-motion: reduce)').matches};
try{const s=JSON.parse(localStorage.getItem('resident-espey-settings'));if(s){settings={...settings,...s};settings.volume=Math.max(0,Math.min(1,Number(settings.volume)||0));}}catch{}
let game;let current='';
const ui={
 isOpen(){return !$('#overlay').hidden;},
 open(eyebrow,title,body,actions,type=''){if(game?.running)game.setPaused(true);current=type;$('#overlay-eyebrow').textContent=eyebrow;$('#overlay-title').textContent=title;$('#overlay-body').innerHTML=body;const container=$('#overlay-actions');container.replaceChildren();for(const a of actions){const b=document.createElement('button');b.textContent=a.label;if(a.primary)b.className='primary';if(a.disabled)b.disabled=true;b.onclick=a.action;container.append(b);}$('#overlay').hidden=false;requestAnimationFrame(()=>container.querySelector('button:not(:disabled)')?.focus({preventScroll:true}));},
 close(){if(current==='death'||current==='ending'){this.home();return;}$('#overlay').hidden=true;current='';if(game?.running)game.setPaused(false);},
 updateContinue(){$('#continue-game').hidden=!game?.readSave();},
 showGame(){$('#title').hidden=true;$('#hud').hidden=false;$('#touch-controls').hidden=!matchMedia('(pointer: coarse)').matches;},
 home(){game.running=false;game.setPaused(true);$('#overlay').hidden=true;$('#hud').hidden=true;$('#touch-controls').hidden=true;$('#chapter-card').hidden=true;$('#title').hidden=false;$('#damage').style.opacity=0;current='';this.updateContinue();},
 intro(c){this.open('CHAPTER '+c.number+' / THE LAST BELL',c.name,c.intro.map(p=>'<p>'+p+'</p>').join('')+'<p class="muted">'+c.objective+'<br>Blue terminals save your progress and restore your health. Open the map to plan your route.</p>',[{label:c.number==='I'?'ENTER THE SCHOOL →':c.number==='II'?'DESCEND INTO THE MAZE →':'WRITE THE LAST PAGE →',primary:true,action:()=>{this.close();game.sound.init();game.sound.play('bell');game.radio('ETHAN ESPEY',c.number==='I'?'Joel. Stay with me. I will get us out.':c.number==='II'?'Landon left the chalk. Follow the marks.':'No more empty pages. No more forgotten names.',6);}}],'intro');},
 start(){this.open('BEGIN YOUR STORY','The Last Bell','<p>The school is infected. The halls no longer lead where they should. You are Ethan Espey, and someone is waiting behind Room 204.</p><div class="setting"><label for="difficulty">Choose your difficulty</label><select id="difficulty"><option value="story">Story — a gentler night</option><option value="survivor" selected>Survivor — the intended experience</option><option value="nightmare">Nightmare — every round matters</option></select></div><p class="muted">A complete three-chapter campaign. Progress saves at terminals, major discoveries, and chapter transitions. Mouse and keyboard recommended; touch controls available.</p>',[{label:'BEGIN STORY →',primary:true,action:()=>{const d=$('#difficulty').value;$('#overlay').hidden=true;game.sound.init();game.newGame(d);}}, {label:'BACK',action:()=>this.close()}],'start');},
 guide(){this.open('YOUR SURVIVAL KIT','Field guide','<div class="control-grid"><div>Move <kbd>W A S D / ARROWS</kbd></div><div>Aim / fire <kbd>MOUSE / CLICK</kbd></div><div>Interact / talk <kbd>E</kbd></div><div>Reload <kbd>R</kbd></div><div>Knife <kbd>F / RIGHT CLICK</kbd></div><div>Dodge <kbd>SPACE</kbd></div><div>Sprint <kbd>SHIFT</kbd></div><div>First aid <kbd>Q</kbd></div><div>Map <kbd>M</kbd></div><div>Notebook <kbd>J</kbd></div><div>Pause <kbd>ESC / P</kbd></div><div>Fullscreen <kbd>BUTTON IN PAUSE</kbd></div></div><p class="muted" style="margin-top:20px">Hold click to fire. Your knife never needs ammunition. A dodge grants a brief window of protection. Red circles warn of incoming attacks: get outside them. On touch screens, the sidearm aims at the nearest visible threat.</p><p class="muted">Gold = objectives. Green = first aid and notebook pages. Blue = checkpoint terminal. Talk to each ally and recover at least four pages to unlock the strongest ending. The Geographer’s Seal clue lives in Landon’s dialogue and Aldo’s notebook.</p>',[{label:'UNDERSTOOD',primary:true,action:()=>this.close()}],'guide');},
 settings(){this.open('ADJUST THE SIGNAL','Settings','<div class="setting"><label for="volume">Sound volume</label><input id="volume" type="range" min="0" max="1" step=".05" value="'+settings.volume+'"></div><div class="setting"><label for="quality">Visual quality</label><select id="quality"><option value="high">High / soft shadows</option><option value="low">Performance / no shadows</option></select></div><div class="setting"><label for="subtitles">Radio subtitles</label><input id="subtitles" type="checkbox" '+(settings.subtitles?'checked':'')+'></div><div class="setting"><label for="motion">Reduce camera shake</label><input id="motion" type="checkbox" '+(settings.motion?'checked':'')+'></div><p class="muted" style="margin-top:20px">Audio is generated locally. Settings and story progress stay in this browser. Performance mode helps on mobile and integrated graphics.</p>',[{label:'SAVE SETTINGS',primary:true,action:()=>{settings.volume=Number($('#volume').value);settings.quality=$('#quality').value;settings.subtitles=$('#subtitles').checked;settings.motion=$('#motion').checked;game.sound.setVolume(settings.volume);game.world.renderer.shadowMap.enabled=settings.quality==='high';game.world.renderer.setPixelRatio(Math.min(devicePixelRatio,settings.quality==='high'?1.8:1));game.world.resize();try{localStorage.setItem('resident-espey-settings',JSON.stringify(settings));}catch{}this.close();}},{label:'BACK',action:()=>this.close()}],'settings');$('#quality').value=settings.quality;$('#volume').oninput=()=>game.sound.setVolume(Number($('#volume').value));},
 credits(){this.open('THE STORY BEHIND THE STATIC','A Chapa Trilogy story','<p>Resident Espey: The Last Bell is an original adaptation inspired by <em>The Chapa Trilogy II</em>, especially its Backrooms serial and Ethan Espey’s outbreak journal.</p><p>Ethan’s notebook becomes a weapon against erasure. Joel’s infection, Hall’s serum, Landon’s chalk, Paul’s current, Jakob’s call, Lil Birdy’s voice, and Zebene’s transformation meet inside one impossible school.</p><p class="muted">Survival-horror inspiration: Resident Evil. Original game code, environments, characters, sound design, and story adaptation. Cinematic cover generated for this game. 3D rendering: Three.js (MIT). This independent game is not affiliated with Capcom.</p>',[{label:'BACK TO THE NIGHT',primary:true,action:()=>this.close()}],'credits');},
 pause(){this.open('THE BELL CAN WAIT','Take a breath','<p class="muted">'+CHAPTERS[game.chapter].name+'<br>'+game.pages.size+' / 6 notebook pages · '+game.allies.size+' / 3 names anchored</p>',[{label:'RESUME →',primary:true,action:()=>this.close()},{label:'FIELD GUIDE',action:()=>this.guide()},{label:'SETTINGS',action:()=>this.settings()},{label:'FULLSCREEN',action:async()=>{try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else await document.exitFullscreen();}catch{}this.close();}},{label:'TITLE SCREEN',action:()=>this.home()}],'pause');},
 page(n){const p=PAGES[n];this.open('NOTEBOOK RECOVERED / '+game.pages.size+' OF 6',p.title,'<p>'+p.text+'</p><p class="muted">Ethan folds the page into his notebook. Another name the school cannot erase.</p>',[{label:'KEEP GOING →',primary:true,action:()=>this.close()}],'page');},
 journal(){let body='<p class="muted">'+game.pages.size+' / 6 pages recovered. Names anchored: '+([...game.allies].map(n=>CHAPTERS[n].npc.name).join(', ')||'none yet')+'.</p>';for(let n=0;n<PAGES.length;n++)body+='<article class="journal-entry"><h3>'+(game.pages.has(n)?PAGES[n].title:'PAGE '+(n+1)+' / MISSING')+'</h3><p>'+(game.pages.has(n)?PAGES[n].text:'A page is still somewhere in the school or the maze.')+'</p></article>';this.open('ETHAN ESPEY’S NOTEBOOK','The names we keep',body,[{label:'CLOSE NOTEBOOK',primary:true,action:()=>this.close()}],'journal');},
 map(){this.open('SURVEY / '+CHAPTERS[game.chapter].place,'Follow the marks','<div class="map-wrap"><canvas id="map-canvas" width="720" height="576" aria-label="Map showing Ethan, walls, objectives, supplies, checkpoint and exit"></canvas></div><div class="map-legend"><span><i></i>Ethan / supplies</span><span><i class="gold"></i>Objective</span><span><i style="background:#76abc8"></i>Checkpoint</span><span><i class="red"></i>Room 204</span></div><p class="muted" style="margin-top:15px">North is up. The center corridor links the rooms. Two objectives and two pages per chapter are farther from the starting sanctuary.</p>',[{label:'RETURN →',primary:true,action:()=>this.close()}],'map');const c=$('#map-canvas'),ctx=c.getContext('2d'),s=24;ctx.fillStyle='#0b1613';ctx.fillRect(0,0,c.width,c.height);game.grid.forEach((r,z)=>r.forEach((v,x)=>{ctx.fillStyle=v?'#34483f':'#14241e';ctx.fillRect(x*s+1,z*s+1,s-2,s-2);}));const dot=(x,z,color,r=5)=>{ctx.fillStyle=color;ctx.beginPath();ctx.arc(x/TILE*s,z/TILE*s,r,0,Math.PI*2);ctx.fill();};game.items.forEach(i=>{if(!i.used)dot(i.x,i.z,['fuse','seal','anchor'].includes(i.kind)?'#d8b572':i.kind==='save'?'#76abc8':'#8fb6a0',i.kind==='page'?4:5);});dot(game.npc.x,game.npc.z,'#aec1b6',5);const ex=CHAPTERS[game.chapter].exit;dot((ex[0]+.5)*TILE,(ex[1]+.5)*TILE,'#ce7056',7);dot(game.player.x,game.player.z,'#e8f2ce',7);ctx.strokeStyle='#e8f2ce';ctx.beginPath();ctx.arc(game.player.x/TILE*s,game.player.z/TILE*s,11,0,Math.PI*2);ctx.stroke();},
 puzzle(){let seq=[];const names=['CURRENT','NORTH','HOME'];const render=(wrong=false)=>{this.open('THE GEOGRAPHER’S SEAL','What remembers the way?','<p>Three rings turn inside the seal. Landon’s words return: water, a compass, a name.</p><p class="muted">'+(wrong?'The rings fall out of alignment. Remember the order in Aldo’s margin.':seq.length?'Aligned: '+seq.join(' → '):'Align the three memories in the right order.')+'</p>',names.map(name=>({label:name,action:()=>{if(name===names[seq.length]){seq.push(name);game.sound.play('pickup');if(seq.length===3){game.puzzleSolved=true;game.save();game.nextChapter();}else render();}else{seq=[];game.sound.play('empty');render(true);}}})).concat([{label:'STEP BACK',action:()=>this.close()}]),'puzzle');};render();},
 finale(){this.open('THE LAST PAGE / YOUR CHOICE','Who gets to come home?','<p>The Gentleman opens a door onto the track at sunrise. Ethan could take it. Behind him, the PA crackles with the voices of everyone the school has taken.</p><p>His notebook is warm in his hands. '+game.pages.size+' pages. '+game.allies.size+' names anchored. A way to remember. Perhaps a way to return.</p><p class="muted">Calling everyone home gives the remembered a chance. Sealing the breach ends the infection, but strands the people inside it.</p>',[{label:'READ THEIR NAMES / BRING THEM HOME',primary:true,action:()=>game.finish('remember')},{label:'SEAL THE BREACH / TAKE THE DOOR',action:()=>game.finish('seal')},{label:'I NEED MORE PAGES',action:()=>this.close()}],'finale');},
 ending(type){const ends={home:{tag:'ENDING I / THE LAST BELL',title:'You wrote us a way home.',body:["Ethan reads the names into the microphone. Joel Honeycutt. Landon Chapa. Luke. Zebene Martine. Coach Hall. The walls try to interrupt. He keeps reading.","A hand closes around his. Joel's eyes are clear. Hall walks out carrying someone the school had almost forgotten. Far away, on a road in Oak Village North, Luke steps into the morning.","The bell rings once. Then, for the first time in three days, it stops. Joel looks at the notebook and smiles. 'You wrote us a way home.'"]},echoes:{tag:'ENDING II / THE NAMES THAT REMAIN',title:'Some voices made it home.',body:["Ethan reads until his voice breaks. The names he has kept become doorways. The others become silence.","At sunrise, someone takes his hand. He cannot tell whether it is Joel or a memory of Joel. Hall's whistle sounds once beyond the track, and the mist lets go of the school.","Ethan opens his notebook. There are empty spaces between the pages. He writes one sentence: I will come back for the names I missed."]},alone:{tag:'ENDING III / ONE SURVIVOR',title:'The school is quiet.',body:["Ethan turns the seal. Room 204 closes like an eye. The static, the infection, the voices: all of it ends at once.","He walks through the Gentleman's door. The track is gold in the morning sun. There is no one waiting at the finish line.","In his notebook, the names are still there. That is the mercy. That is the price. Somewhere beyond the last page, a bell rings."]}};const e=ends[type],s=game.stats,minutes=Math.floor(s.seconds/60),seconds=Math.floor(s.seconds%60);$('#hud').hidden=true;$('#touch-controls').hidden=true;this.open(e.tag,e.title,e.body.map(p=>'<p>'+p+'</p>').join('')+`<div class="ending-score"><span><strong>${minutes}:${String(seconds).padStart(2,'0')}</strong>TIME SURVIVED</span><span><strong>${game.pages.size}/6</strong>PAGES KEPT</span><span><strong>${game.allies.size}/3</strong>NAMES ANCHORED</span><span><strong>${s.shots?Math.round(s.hits/s.shots*100):0}%</strong>ACCURACY</span></div><p class="muted" style="margin-top:18px">${type==='home'?'All names anchored. The story is yours.':'Recover at least four notebook pages and speak to every ally for the strongest ending.'}</p>`,[{label:'RETURN TO TITLE →',primary:true,action:()=>this.home()},{label:'THE STORY',action:()=>this.credits()}],'ending');},
 death(){this.open('ETHAN ESPEY / SIGNAL LOST','The story is not over.','<p>The walls take another breath. Somewhere, a page refuses to go blank.</p><p class="muted">Return to your latest checkpoint with restored vitals. Dodge during the red warning, keep your distance, and use your knife when ammunition runs dry.</p>',[{label:'TRY AGAIN →',primary:true,action:()=>{$('#overlay').hidden=true;current='';game.retry();}},{label:'TITLE SCREEN',action:()=>this.home()}],'death');}
};
try{game=new Game(ui,settings);ui.updateContinue();window.ResidentEspey=Object.freeze({snapshot:()=>game.snapshot()});}catch(error){console.error('Unable to initialize Resident Espey:',error);$('#fatal').hidden=false;$('#title').hidden=true;}
$('#new-game').onclick=()=>ui.start();$('#continue-game').onclick=()=>{game.sound.init();if(game.continueGame())ui.showGame();};$('#how-to').onclick=()=>ui.guide();$('#settings').onclick=()=>ui.settings();$('#credits').onclick=()=>ui.credits();$('#pause-button').onclick=()=>ui.pause();$('#map-button').onclick=()=>ui.map();$('#journal-button').onclick=()=>ui.journal();
document.addEventListener('keydown',e=>{if(e.code==='Tab'&&ui.isOpen()){const nodes=[...$('#overlay').querySelectorAll('button:not(:disabled),select,input')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
